cd "$BENCHMARK_WORKSPACE" && cat > /tmp/test_bnd.c << 'EOF'
#include <stdio.h>
#include <capstone/capstone.h>

int main() {
    csh handle;
    cs_insn *insn;
    size_t count;

    // BNDMOV bnd0, bnd1  (66 0f 1a c1)
    unsigned char code[] = {0x66, 0x0f, 0x1a, 0xc1};

    if (cs_open(CS_ARCH_X86, CS_MODE_64, &handle) != CS_ERR_OK) {
        printf("Failed to open capstone\n");
        return -1;
    }

    cs_option(handle, CS_OPT_DETAIL, CS_OPT_ON);

    count = cs_disasm(handle, code, sizeof(code), 0x1000, 0, &insn);
    if (count > 0) {
        for (size_t i = 0; i < count; i++) {
            printf("0x%"PRIx64":\t%s\t\t%s\n", insn[i].address, insn[i].mnemonic, insn[i].op_str);

            if (insn[i].detail) {
                cs_x86 *x86 = &(insn[i].detail->x86);
                printf("  operand count: %d\n", x86->op_count);
                for (int j = 0; j < x86->op_count; j++) {
                    printf("    operand %d: type=%d size=%d\n", j, x86->operands[j].type, x86->operands[j].size);
                }
            }
        }
        cs_free(insn, count);
    } else {
        printf("Failed to disassemble\n");
    }

    cs_close(&handle);
    return 0;
}
EOF
